from lib import *
S = SS('t13')
steps = [
    step("正常提交的事务消息。先把半消息发到 broker(0 ms,此时消费者看不到),再执行本地事务——这里故意让它慢 1.5 秒:1643 ms 本地事务提交,监听器返回 COMMIT_MESSAGE,1645 ms 发送结果是 SEND_OK、local=COMMIT_MESSAGE,13 ms 之后消费者收到 o-1。半消息发出后到本地事务提交的这 1643 ms 里,消费者什么都没收到;订单库里 o-1 有 1 行。半消息保证的是“消息在本地事务提交之前不可见,提交之后才可见”。", t=tl(S(1)), mark=lidx(S(1), 'LOCAL_TX_COMMITTED', 'CONSUMED o-1'), done=lidx(S(1), 'HALF_SENT o-1'), b=bars([['半消息发出 → 本地事务提交 ms(消费者收不到)', 1643, '1643'], ['本地事务提交 → 消费者收到 ms', 13, '13']], 1700, cur=[0], mark=[1]), kv=KV([['半消息', '先发到 broker,消费者不可见'], ['本地事务', '提交后返回 COMMIT_MESSAGE'], ['可见', '提交之后 13 ms 消费者收到']], ['半消息'])),
    step("本地事务回滚:监听器在 620 ms 返回 ROLLBACK_MESSAGE(发送结果 local=ROLLBACK_MESSAGE),订单库里 o-2 有 0 行。等了 5 秒,消费者收到 o-2 的次数是 0:半消息被丢弃,下游永远不会看到一个本地没成功的订单。", t=tl(S(2)), mark=lidx(S(2), 'LOCAL_TX_ROLLED_BACK'), done=lidx(S(2), '等了 5 秒'), b=bars([['订单库里 o-2 的行数', 0, '0'], ['消费者收到 o-2 的次数', 0, '0']], 1, done=[0, 1]), kv=KV([['回滚', '半消息被丢弃'], ['订单库', '0 行'], ['消费者', '收到 0 次']], ['回滚'])),
    step("本地事务其实提交了,但监听器返回 UNKNOW(比如提交成功、应答丢了)。半消息一直悬着,broker 等过 transactionTimeOut(这里 3000 ms)之后回查:5502 ms 时生产者收到第 1 次回查 CHECK_BACK o-3 times=1,查库发现订单存在,回复 COMMIT,11 ms 之后消费者收到 o-3,共回查 1 次、消费者收到 1 次。回查靠的是业务库里的事实——订单在不在。", t=tl(S(3)), mark=lidx(S(3), 'CHECK_BACK o-3'), done=lidx(S(3), 'CONSUMED o-3', '回查发生在'), b=bars([['半消息发出 → 回查 ms', 5502, '5502'], ['回查 → 消费者收到 ms', 11, '11']], 5600, cur=[0], mark=[1]), kv=KV([['UNKNOW', '半消息悬着'], ['回查', '过了 transactionTimeOut 后 broker 来问'], ['答案', '查本地订单:在 → COMMIT']], ['答案'])),
    step("生产者在本地事务提交之后、返回结果之前被 kill -9(订单已写进库,半消息悬在 broker 上),换一个新的生产者进程(同一个 producer group)上线。第一次试:新生产者只是启动、没有声明 topic。它在 385 ms 启动完毕,可是收到回查 0 次;broker 的 transaction.log 里连续 3 行 “Check transaction failed, channel is null. groupId=pg-order”,第 4 行 “Put checked-too-many-time half message to TRANS_CHECK_MAXTIME_TOPIC OK”——回查没人接,到了 3 次上限(这里配的)后半消息被丢弃,消费者收到 o-4 0 次,而订单库里 o-4 有 1 行。第二次试:新生产者声明了 topic(启动时就取路由并向 broker 注册):461 ms 启动,2997 ms 收到回查 CHECK_BACK o-4b times=1 订单存在=true,回复 COMMIT,3003 ms 消费者收到 o-4b。能回查的人必须真的在 broker 那里注册过。", t=tl(S(4)), mark=lidx(S(4), 'channel is null', 'checked-too-many-time', '消费者收到 o-4 0 次'), done=lidx(S(4), 'CHECK_BACK o-4b', 'CONSUMED o-4b'), b=bars([['没声明 topic:收到回查次数', 0, '0'], ['没声明 topic:消费者收到 o-4', 0, '0(订单已提交)'], ['声明了 topic:收到回查次数', 1, '1'], ['声明了 topic:消费者收到 o-4b', 1, '1']], 1, mark=[0, 1], done=[2, 3]), kv=KV([['没声明 topic', 'broker 找不到回查对象,3 次后丢弃半消息'], ['声明了 topic', '启动时注册,回查到达并 COMMIT'], ['后果', '订单已提交、消息没发出']], ['后果'])),
    step("生产者在本地事务提交之前被 kill -9(订单没写进库),声明了 topic 的新生产者上线后收到回查:4368 ms 时 CHECK_BACK o-5 times=1 订单存在=false,回复 ROLLBACK。等了 5 秒,订单库里 o-5 有 0 行、消费者收到 o-5 0 次——没有写成功的订单,消息也没有发出。回查把“本地事务到底成没成”交给能查本地库的人。", t=tl(S(5)), mark=lidx(S(5), 'CHECK_BACK o-5'), done=lidx(S(5), '等了 5 秒'), kv=KV([['订单没写进库', '回查答 ROLLBACK'], ['消息', '不发出'], ['结果', '本地与消息一致(都没有)']], ['结果'])),
    step("回查一直查不出结果(一直返回 UNKNOW)时,broker 最多回查 transactionCheckMax 次(这里配成 3 次,默认 15):3423 ms、6426 ms、9430 ms 各回查一次(times=1、2、3),都回复 UNKNOW;之后 broker 的 transaction.log 里出现 “Put checked-too-many-time half message to TRANS_CHECK_MAXTIME_TOPIC OK”。消费者收到 o-6 0 次,而订单库里 o-6 有 1 行——本地事务其实提交了,但消息被 broker 丢掉了:本地有订单、下游收不到。回查的答案必须能回答出来,否则兜底是“丢”。", t=tl(S(6)), mark=lidx(S(6), 'CHECK_BACK o-6 times=3', 'checked-too-many-time'), done=lidx(S(6), '回查共 3 次'), b=bars([['回查次数(上限 3)', 3, '3'], ['消费者收到 o-6', 0, '0'], ['订单库里的 o-6', 1, '1(本地有、下游没有)']], 3, cur=[0], mark=[1, 2]), kv=KV([['一直 UNKNOW', '回查到上限就丢弃半消息'], ['结果', '本地有订单、下游收不到'], ['要求', '回查必须能查出本地事务的结果']], ['要求'])),
]
A = mkartt('t13', 13, '分布式事务,事务消息,半消息,回查,RocketMQ,MySQL,真实验证,动画演示',
    '用真实的 RocketMQ 5.5.1 和 MySQL 实测事务消息:半消息在本地事务提交前对消费者不可见(1643 ms),回滚则丢弃;返回 UNKNOW 时 broker 回查并按订单是否存在 COMMIT;生产者 kill -9 后,没声明 topic 的新生产者收不到回查,3 次后半消息被丢弃,声明了 topic 的新生产者 2997 ms 收到回查并 COMMIT;回查一直 UNKNOW 到上限也会丢弃。',
    '事务消息(半消息 + 回查)想让“本地事务提交”和“消息发出”要么都成要么都不成。它怎么保证?本地事务结果丢了怎么办?生产者崩溃后谁来回答?回查答不上来又会怎样?这篇用真实的 RocketMQ 和 MySQL,把这六种情形逐个跑出来,也撞上了一个新生产者收不到回查的坑。',
    [('1643 ms', '半消息发出之后、本地事务提交之前,消费者看不到消息的这段时间(提交后 13 ms 收到)'), ('0 次 vs 1 次', '生产者 kill -9 后,没声明 topic 与声明了 topic 的新生产者收到回查的次数'), ('3 次', '回查一直 UNKNOW 时(本篇配置的上限),broker 回查几次后丢弃半消息')],
    [('半消息', '<p>先把半消息发到 broker,此时消费者看不到;本地事务提交后返回 COMMIT_MESSAGE,消息才对消费者可见。</p>'),
     ('回滚', '<p>本地事务回滚返回 ROLLBACK_MESSAGE,半消息被丢弃,下游不会看到没成功的订单。</p>'),
     ('回查', '<p>本地事务结果没告诉 broker(UNKNOW),broker 等 transactionTimeOut 之后回查,生产者查库:订单在就 COMMIT。</p>'),
     ('生产者崩溃后由谁回答', '<p>kill -9 后换一个新生产者(同一个 group)上线。只启动、没声明 topic 的新生产者没有向 broker 注册,broker 回查找不到人,3 次后丢弃半消息,订单已提交而消息没发出;声明了 topic 的新生产者启动时取路由并注册,回查到达,按订单是否存在回答。</p>'),
     ('本地事务没提交', '<p>崩溃发生在提交之前,回查发现订单不在,回复 ROLLBACK,消息不发出,两边一致。</p>'),
     ('回查答不上来', '<p>一直返回 UNKNOW,回查到上限后 broker 丢弃半消息:本地有订单、下游收不到。回查必须能给出确定答案。</p>')],
    steps,
    [ENV_T + '。本篇用官方 bin 包的 RocketMQ 5.5.1(NameServer + 单 Broker,Java 17,客户端 rocketmq-client 5.5.1 的 TransactionMQProducer / DefaultMQPushConsumer),本地事务写 MySQL 26.7.0(Connector/J 26.7.0);broker 配置 transactionTimeOut=3000 ms、transactionCheckInterval=3000 ms、transactionCheckMax=3(默认 15);JVM 的 user.home 指到实验目录,日志不写进家目录;半消息可见性、回查结果由生产者与消费者进程的输出时间戳和 broker 的 transaction.log 佐证',
     '没有验证:RocketMQ 的 gRPC 客户端(rocketmq-clients)与 Proxy 模式下的事务消息;多个 broker / 多个生产者实例时回查具体发给哪一个;默认配置(transactionCheckMax=15、回查间隔 30 秒)下的表现;“没声明 topic 的新生产者收不到回查”的原因我只用 broker 日志(channel is null)与“声明了 topic 就收到”的对照佐证,没有读 RocketMQ 的客户端源码确认其注册流程;消费端重复投递(第 14、15 篇)'],
    '事务消息')
